CORPUS = [
# ---------- 2024 年第 3 期 ----------
{"issue": "2024-3", "column": "法治天地", "title": "维护领海主权视域下我国海疆历史档案编研证据链构建", "authors": "华林 谢梦晴 冯安仪 彭媛媛",
 "abstract": "我国现存有丰富的海疆历史档案，国外相关政府部门、文化机构也产生了部分涉及我国海疆问题的档案文件，从维护国家领海主权的视角，探讨海疆历史档案编研证据链构建问题，对更好地开发历史档案证据，维护国家领海主权完整有现实意义。在领海争端形势日趋严峻的形势下，分析海疆历史档案编研现状，提出档案编研证据链构建问题，从海疆历史档案概念界定、资源特征，及其档案编研证据链构建理论阐释、实现途径与实证研究等维度，解决档案编研产品证据链构建理论、方法与实践问题，可优化档案编研工作，开发多样性海疆历史档案证据性产品，为开展海洋主权意识教育、维护国家领海主权提供档案文化助力。"},
{"issue": "2024-3", "column": "法治天地", "title": "论《档案法》与《刑法》的衔接", "authors": "谷永超",
 "abstract": "《档案法》与《刑法》存在衔接不畅的问题，尽管档案法犯罪条款通过明示和暗示的方式发挥了提示引证、限定刑法处罚范围及解释参照等功能，发挥了联通《档案法》与《刑法》的作用，但二法衔接仍存在诸多不足。二法衔接问题在《档案法》全面修订之后有所缓和，但仍存在概念内涵不一致、实行行为类型不明确、犯罪圈划定立场不统一等问题，档案法注重概念思维与刑法注重类型思维的冲突尤为明显。因此，有必要在《档案法》中设立真正的附属刑法，同时以“群+类型”行为为核心整合档案法犯罪条款与档案犯罪，从形式和实体两方面推动二法的顺畅衔接。"},
{"issue": "2024-3", "column": "法治天地", "title": "档案数字化转型中隐私保护的理论优化与制度完善", "authors": "白银",
 "abstract": "档案开放利用是档案数字化转型和数字经济发展的基本需求，也是其与隐私保护内生性冲突加剧的关键所在。档案数字化建设的体系化、社会化、智能化、共建化、记忆化需求，加大了隐私侵害风险和保护难度，致使传统“自决式”“防御式”等个人主义保护范式式微。而有必要补强适用“隐私即信任”理论，通过引入档案“信息受托人”模式、强化档案可信技术应用、完善档案领域社会信用治理机制等措施，来改良和维护可信任档案数据关系，以实现档案开放利用与隐私保护的平衡。"},
{"issue": "2024-3", "column": "实践经纬", "title": "电子文件元数据捕获存在问题及应对策略", "authors": "蔡盈芳 高强",
 "abstract": "我国电子文件归档过程中存在元数据捕获不全等问题，尤其是机构人员实体元数据、业务实体元数据、实体关系元数据捕获不全，给电子文件的真实性、完整性和长期保存埋下了安全隐患。通过对国内多个标准规范对比分析发现，机构人员实体元数据、业务实体元数据、实体关系元数据属于序列（元组）型元数据，采集方式包括多次捕获多个属性值，或一次捕获反映多种关系的多个属性值，存储方式包括转换成文本存储于一个备注型字段中，或采取多元数据表形式存储相关元数据，元数据的呈现可以通过分区或分标签页形式实现。"},
{"issue": "2024-3", "column": "实践经纬", "title": "数据档案化的浙江探索：模式路径、实施经验与发展趋势", "authors": "章燕华 石晶",
 "abstract": "以浙江省“最多跑一次”改革事项电子化归档、嘉兴市重要业务系统结构化数据归档治理、嵊州市“个人全生命周期档案”综合智治应用三个典型案例为研究对象，分析并比较数据档案化的浙江探索在实践背景与发展方向、参与主体与工作机制、主要目标与基本任务、原始驱动力与导向、主导机构与职能、解决思路与方案等方面的异同，引申出对数据档案化的实践模式、实施经验与发展趋势三方面的初步思考。通过对浙江探索的研究发现，数据档案化至少存在“保管驱动型”“应用驱动型”两大模式下的三大路径；数据档案化的实施经验包括理念与行动上的“顺势而为”与“发展导向”，职责与机制上的“协同治理”与“守责共赢”，路径与方案上的“守正创新”与“因地制宜”；数据档案化的发展趋势包括实践探索朝多元化模式路径发展、从“档案化治理”向“数据化服务”延伸，顶层设计朝“档案数据化”与“数据档案化”统筹规划、重视激励和提升档案领导干部改革创新能力推进，理论研究朝重塑数智时代档案学理论、构建中国档案学自主知识体系升级。"},
{"issue": "2024-3", "column": "实践经纬", "title": "我国红色档案资源建设现状与未来发展", "authors": "方雯灿 刘越男",
 "abstract": "通过调研中央档案馆等45所副省级以上综合档案馆门户网站，辅助文献调研，从政策引导、机制保障和业务开展三个层面梳理我国红色档案资源建设的具体情况。调研发现，红色档案资源建设工作政策引导初步建立，机制逐步完善，业务全面开展，但在立法的全面性、规范供给、征集的针对性与持续性、数字资源建设程度、开发利用深度，以及开放共享力度等方面存在不足。因此，有必要从立法保障、制度细化、征集渠道、技术应用、跨界探索，以及共建共享等方面持续优化。"},
{"issue": "2024-3", "column": "实践经纬", "title": "档案学视角下背景（Context）的概念、构成与功能", "authors": "龙家庆",
 "abstract": "背景是档案学理论的核心概念，是来源原则和新来源观的有益补充。对档案行业词典和标准指南中所见“背景”一词予以梳理，归纳出档案学视角下的术语称谓和概念内涵，发现其隶属于信息资源管理学科术语体系，并致力于支撑档案业务活动。同时，在遵循文件档案管理规律基础上，参考行业领域“背景信息框架”，抽取出9个背景实体，并结合实例对其构成要素、构成层次和应用情况进行三维解析。经过结构性分析后发现，档案领域的背景管理具有显著功能，包括增进对来源原则的认识、加深对文件档案管理现象的理解、促进档案证据价值的发挥。"},
{"issue": "2024-3", "column": "古文书学", "title": "档案学视野中的古文书学：西方经验与中国路径鸟瞰", "authors": "梁继红",
 "abstract": "古文书学是西方自17世纪末以来创建的独立学科，与档案学有深刻的渊源与互动关系。自晚清开始，西方古文书学经由不同渠道传入中国。在它的参照下，中国现代档案学视野下的中国古文书学研究开始规划与组织，并与中国治牍传统相呼应，呈现出以中国文书为对象的属性特征。1980年代初，张我德在档案学框架下自觉以中国古文书学研究为目标，创建面向清代文书的古文书学知识体系，奠定中国古文书学作为档案学分支学科的基础。中国古文书辞典及其编纂，具有重要意义。这是自1930年代学者提出但最终未能实现的百年学术课题，是当代中国古文书学研究必须接续的重要历史使命。"},
{"issue": "2024-3", "column": "古文书学", "title": "古文书与中国历史研究", "authors": "阿风",
 "abstract": "古文书是事件发生同步的历史记录，是历史研究的基础史料。近代以来的中国史学，虽然包括简牍文书、敦煌吐鲁番文书、明清档案、徽州文书等古文书研究一直存在，却分属于档案学、历史文献学等不同的学科，一直缺乏一个将公私文书统一起来研究的“古文书学”学科。事实上，无论是公文书，还是私人契约；无论是出土文书，还是传世文书；无论是简牍文书，还是纸质文书，它们都是当时治理国家与调整社会关系的原始文件，它们的“文书”性质决定了其与一般的编纂史料处于不同的层面。因此，非常有必要将公文书与私文书从历史文献学与档案学中分离出来，建立起独立的“古文书学”，才能够充分发掘出“文书”作为第一手资料的价值。"},
{"issue": "2024-3", "column": "古文书学", "title": "日本中世纪古文书学的发展历程与研究展望", "authors": "佐藤雄基",
 "abstract": "日本中世纪古文书学的发展起源于德国古文书学的影响，这一学科自江户时代至明治时期经历了显著发展，重点关注文书的分类和政治权力的演变。随着时间的推移，研究重心从传统的样式分析转向文书的实际应用和其在社会中的实践作用。新兴古文书学提高了对文书原件的关注，将相关人员的行为纳入研究视野，并与社会史研究产生联动。此外，日欧古文书学的比较研究也为更深层次的学术交流和讨论提供了可能性。"},
{"issue": "2024-3", "column": "古文书学", "title": "砧基簿与寺院田产登记簿册演变探究——以东南地区为中心", "authors": "吕珊珊",
 "abstract": "在明代以后的寺院中，砧基簿由官方赋税册籍演变为财产登记和寺志记录的文册。其原为南宋时期土地登记的官方册籍，也是田土交易中的重要凭证。明太祖的改革后，鱼鳞册系统的文书成为官方登记土地的主体，砧基簿作为官方登记凭证的存在逐渐消失，但其形制与名称被寺院继承，用于登载包括田产在内的常住物或寺院沿革等内容。寺院在置办与清理田产过程中，受不同时期土地清丈政策的影响，除了砧基簿，还衍生出细号册等满足赋税需求的田产登记簿册。近代，民国政府对产权观念的重视与重构地籍秩序的需要，使得寺院田产登记簿册开始出现以土地所有权状的内容为中心的产业表、产业清册等类型。"},
{"issue": "2024-3", "column": "档案教育", "title": "新时代信息资源管理学科的问题审视与发展路径分析", "authors": "王协舟 胡诚 陈晶晶",
 "abstract": "正式更名后，信息资源管理一级学科迈进高质量内涵式发展新时代，但在学科专业与社会群体认知、人才培养与行业事业发展、学术研究与话语体系建设等方面仍然存在诸多问题。为了更好激发学科发展活力，在理清学科发展脉络上，需要优化完善目录体系，调整学科专业布点，深耕厚植传统学科，融合发展交叉学科；在优化人才培养策略上，需要重视顶层设计、动态调整人才培养方案，强化协同联动、全面革新专业教材体系，致力智慧教育、深度融合智能信息技术；在科学研究范式创新上，需要定义“单学科”主体身份，组建“多学科”研究团队，锁定“跨学科”前沿课题，融入“超学科”学术思维，开展“有组织”科学研究，构建“场景式”学科应用。"},
{"issue": "2024-3", "column": "档案教育", "title": "数智时代档案学专业人才培养的需求、困境与进路——基于教师视角的调查", "authors": "许晓彤 张婧妍 张伟霞 曲春梅",
 "abstract": "数字转型、智能升级背景下聚焦档案学专业人才培养关键需求与问题，有助于提高档案人才培养质量，提升档案智力支撑能力。通过文献研究、政策调研和问卷调查，梳理专业教师视角下数智时代档案学专业人才培养的概况、需求与困境，分析人才培养进路。来自全国28所高校的96名档案学专业教师参与调查。调查显示，档案学专业人才培养面临着技术要素融入与数据范式转型、档案资源深度挖掘与开发利用、提炼数智时代特色专业素养的迫切需求，同时需应对学生知识体系滞后于智能化时代趋势、专业能力难胜任档案资源深度开发需求、档案政策法规教育时代关照不足、数智素养基础不牢等现实困境。"},
# ---------- 2024 年第 4 期 ----------
{"issue": "2024-4", "column": "本刊专稿", "title": "国家数据战略下建构中国自主的档案学知识体系的使命与路径", "authors": "张斌 张旭 杨文",
 "abstract": "在国家数据战略下建构中国自主的档案学知识体系，是中国档案学观照时代实现守正创新的必然之举，具有重要的社会价值、学科价值、学理价值、实践价值。面对国家数据战略下档案学研究体系的丰富，中国自主的档案学知识体系建构必须勇担完善中国档案学知识生产机制、提炼中国档案学的本土化经验、推进中国档案经验学理化阐释、回应中国档案事业变革与创新的使命，立足会逢其适的时代发展机遇、鲜活丰富的档案实践样态、日臻完备的档案研究体系、规模空前的档案教育体系，以开放包容为理念，融合国外优秀成果与本土经验；以知识创新为目标，回应中国重大理论和实践问题；以国家战略为牵引，主动推进档案学学科数字转型；以学科建设为基点，提升数智时代档案学科话语权；以服务社会为宗旨，聚焦新时代档案智库参考价值。"},
{"issue": "2024-4", "column": "本期专题", "title": "从客体全宗到面向对象的可信数据体：数据档案化治理方法论探析", "authors": "刘越男",
 "abstract": "数字中国战略下，数据档案化治理是档案部门参与、贡献国家数据资源体系建设的新路径。以浙江省嵊州市个人全生命周期数据档案化治理实践为案例，探讨跨部门数据治理场景中的档案方法贡献。研究发现全宗理论是数据档案化治理方法论的理论基础，即以业务为主线，面向对象建立跨部门的客体全宗，并通过全过程记录保证其数据可信，通过全面质量检测验证其可信。"},
{"issue": "2024-4", "column": "本期专题", "title": "根据业务对象组织数据体的结构化数据归档路径探析——基于勘探开发结构化数据归档实践的思考", "authors": "王强 符京生",
 "abstract": "在数字转型和数据要素背景下，结构化数据归档对于档案资源体系建设至关重要。结构化数据归档面临数据价值鉴定、归档数据组织、归档方式选择的困境，提出根据业务对象组织数据体的归档路径，即确定业务对象——鉴定数据价值——组织归档数据体——选择归档方式——开展长期保存。以勘探开发结构化数据归档为例进行实证研究，为结构化数据归档提供一种可行方法。"},
{"issue": "2024-4", "column": "本期专题", "title": "机关业务系统结构化数据归档管理的实践与思考", "authors": "金培中 陆建军 张雷 李雪彤",
 "abstract": "机关业务数据归档是关系国家档案资源建设的重要问题。为了加强机关业务数据归档管理，提升档案数据治理水平，以浙江省嘉兴市机关业务系统结构化数据归档管理实践为样本，剖析数据归档管理面临的理念滞后、工具缺失、衔接不畅、监管有限等挑战，并从“收-管-存-用”全链条构建数据归档的业务路径，从归档数据包设计、区块链可信存证技术应用等探索技术方法，从档案、业务、技术多部门融合共治等探讨组织保障方式，多维度探寻破解难题的新方法新路径。"},
{"issue": "2024-4", "column": "本期专题", "title": "重大科技项目科学数据归档路径初探", "authors": "张静 付玥甜 何思源 潘亚男",
 "abstract": "推进重大科技项目的科学数据归档工作，对于科技信息资源的集中统一管理和高效共享利用具有重要意义。科学数据归档工作在“归档”的统一认识、组织管理体系和制度规范建设，以及归档模式选择等方面面临较大挑战。通过中国科学院9家试点单位的案例研究和行动研究，构建了科学数据归档的一般路径，包括开展科学数据管理现状调查、确定归档范围、选择归档模式和提出归档科学数据要求等，总结逻辑归档和物理归档两种模式在科学数据归档工作中的实施前置条件与要求，为复杂数据环境下归档研究和实践提供参考。"},
{"issue": "2024-4", "column": "特约组稿", "title": "我国政务数据治理政策主题演化与运行特征", "authors": "卢小宾 杨紫楠",
 "abstract": "政务数据与国民经济息息相关，对其收集、处理、开放、利用等数据管理环节进行治理是释放政府部门数据要素价值的基础和疏通政务数据资源大循环的核心保障。明确我国政务数据治理政策的发展脉络与实践路径能够为政策的完善和创新提供参考依据。运用LDA主题模型对我国近30年国家层面出台的273份政务数据治理政策的主题及主题演化趋势进行分析，并结合政策工具进行量化研究，揭示了目前政策文件的运行效力。研究发现：我国政务数据治理政策历经“萌芽”“形成”“发展”三个阶段，政务数据治理导向和政策目标在发展过程中不断演化，其覆盖的主题范围明显扩大。根据政策工具统计结果显示，政务数据治理政策存在环境型政策工具使用过溢、供给型政策工具不足、需求型政策工具短缺等现象。"},
{"issue": "2024-4", "column": "特约组稿", "title": "基于AIOps视角的政务热线数据赋能机制框架与实现路径", "authors": "周庆山 刘惠 黄钰婷 黄国彬",
 "abstract": "政务热线作为政府及时了解民生、有效响应民众关切、参与社会治理的互动通道，动态产生了反映民生诉求的大量数据。如何通过数据赋能实现政务热线转型是数字政府建设的重要议题。在“智能运维（AIOps）”视角下，对多来源资料进行文本分析，总结多案例实践经验，结合政务热线的功能定位与运行模式，系统梳理了数据赋能政务热线转型的逻辑，最终构建了政务热线数据赋能机制的关键要素。并基于关键要素，从多方合作、标准规范、专家团队、人机协同等四个维度探讨政务热线数据赋能的优化路径。"},
{"issue": "2024-4", "column": "实践经纬", "title": "技术驱动下档案公共服务价值共创：逻辑转向、作用机理及实现路径", "authors": "宋帆帆 苏君华",
 "abstract": "技术作为驱动档案公共服务价值共创的重要力量，促使主体结构由单一个体转向生态系统；主体关系由单向线性转向多元互动；服务过程由业务驱动转向数据驱动；发生场域由在地化转向脱域化。结合技术驱动的特性与公共价值的内涵，揭示了技术驱动下档案公共服务价值共创的作用机理，提出档案机构要紧贴时代脉搏，立足用户需求，开放档案数据，奠定档案服务根基；培育公共精神，增强数字参与能力；建构互动场域，激发档案服务活力；完善制度建构，保障技术运行有效，进而不断增强档案机构与用户的连接，提升用户体验，实现档案公共服务价值共创。"},
{"issue": "2024-4", "column": "实践经纬", "title": "公共数据开放的“档案参与”：现状调研、影响因素与进路选择", "authors": "张博闻",
 "abstract": "参与公共数据开放有助于档案工作融入数字时代的公共服务体系。在梳理现有研究成果的基础上，从数据类型、数据量、数据格式等6个方面对我国已建立的省级公共数据开放平台中档案部门的数据发布情况展开了调研；通过对档案部门与数据管理部门工作人员的访谈，运用扎根分析方法归纳出了价值理念、政策法规、体制机制、技术方法四个方面的影响因素；据此提出公共数据开放“档案参与”的进路，包括：厘清档案部门功能定位、完善政策法规制度体系、强化开放数据质量控制、坚持渐进融通技术路线，以期推动档案部门变革工作思路，拓展工作范围，优化工作模式，实现档案治理现代化。"},
{"issue": "2024-4", "column": "实践经纬", "title": "澳大利亚国家档案馆数字转型的瓶颈与新突破——基于“图恩评估”的深度分析", "authors": "李思艺 谢丽",
 "abstract": "伴随各国陆续制订数字转型规划，数字转型在世界范围内呈现蓬勃发展态势，然而具体领域或机构的数字转型落实情况仍有待考证。以澳大利亚联邦政府对澳大利亚国家档案馆数字转型现状的评估为切入点，对评估报告、相关政策性文本、工作报告等进行深入分析，探索在国际档案界久享盛誉的档案机构在数字转型中的实际运作情况。分析发现在政府数字转型中承担重要角色的澳大利亚国家档案馆面临职能权力较弱、数字能力不足、可持续发展所需资源匮乏等瓶颈，目前正在尝试通过制订全面适配数字转型的《档案法》、建立以澳大利亚国家档案馆为中心的联邦政府信息管理崭新模式、优化资源配置等方式来实现数字转型的新突破。"},
{"issue": "2024-4", "column": "法治天地", "title": "档案犯罪刑罚制度：问题检视、域外经验与完善思路", "authors": "蒋云飞 袁奎",
 "abstract": "作为档案安全刑法保障的“最后防线”，档案犯罪刑罚具有遏制和预防犯罪的重要功能。通过对档案犯罪刑罚的实证检视和规范分析发现，我国档案犯罪刑罚总体因刑罚种类单一而且缺乏威慑力，因裁量标准宽泛而导致量刑失准，因过度适用缓刑而难以实现特殊预防目的，这一定程度上削弱了档案犯罪刑罚的效果。法国、美国、新加坡等国家在档案犯罪刑罚理念设计、刑罚种类配置、刑罚裁量等方面有诸多创新之处，其中的成熟经验值得我国镜鉴。未来应当立足于档案犯罪之一般预防和特殊预防目标，通过增补刑罚种类并明确其适用规则、统一刑罚裁量标准、规范缓刑适用等方式，完善我国档案犯罪刑罚制度。"},
{"issue": "2024-4", "column": "法治天地", "title": "人事档案遗失的精神损害赔偿责任及其规范适用", "authors": "王振宇",
 "abstract": "人事档案遗失能否触发精神损害赔偿责任的问题，在理论层面和实践层面皆不无分歧。考虑到保护档案相对人权利、促进档案领域法体系衔接和应对档案数字化发展趋势的需求，明确此种情形下精神损害赔偿责任的可适用性实为必要。就精神损害赔偿责任的解释路径而言，“特定物说”与档案学理论存在龃龉，“隐私权说”与现行法体系多有不合；相形之下，“信息权说”则准确地揭示了人事档案的权利属性，能够为责任适用提供充分的理论依据。人事档案遗失作为个人信息保护的特殊场景，现行法上对其适用精神损害赔偿责任的规定较为模糊，故应通过对归责原则、损害类型、损害程度和赔偿数额等内容的解释与辨正，进一步推动精神损害赔偿责任的规范适用和《档案法》的全面实施。"},
# ---------- 2024 年第 6 期 ----------
{"issue": "2024-6", "column": "理论纵横", "title": "档案数据要素价值内涵要义与生成机理", "authors": "金波 杨鹏 刘娟娟",
 "abstract": "数据是经济社会发展的新型生产要素，数据要素化是大数据时代的核心特征。档案数据作为高价值的原生历史记录和珍贵数字记忆，以其真实可靠、权威凭证性成为独具特色的生产要素，档案数据要素价值成为大数据时代档案价值新形态。立足档案数据生存环境与运行规律，揭示档案数据要素价值内涵属性与特征功能，从资源化产生价值、资产化创造价值和资本化增加价值，解析档案数据要素价值生成机理，夯实档案数据要素价值理论基础，破析档案数据元问题，完善档案数据理论知识体系，激活档案数据要素价值，推动新质生产力创新发展。"},
{"issue": "2024-6", "column": "理论纵横", "title": "档案叙事与共情：理论阐释与实证分析", "authors": "连志英 余敏",
 "abstract": "档案叙事是档案叙事者基于特定的背景，面向特定的受叙者，围绕特定的主题，对档案及其内容进行选择、组织、呈现，以传达特定意义的行为和过程，其实质是档案叙事者和受叙者围绕档案叙事文本形成的互动。好的档案叙事应是能引发受叙者共情的叙事，受叙者的共情也会促使他们实施亲档案馆行为。根据互动仪式链理论，档案叙事引发共情包括共同在场、互动、共情等阶段，而档案叙事者的身份、档案叙事文本的故事和话语、受叙者自身经历及其所处社会文化背景等都会对共情的促发产生影响。档案馆如果要增强档案叙事引发共情的效果，需具备叙事思维、聚焦故事内容和话语形式写好档案叙事文本、邀请事件亲历者和受叙者参与档案叙事，并着力营造通感档案叙事场域。"},
{"issue": "2024-6", "column": "理论纵横", "title": "权力的谱系——福柯论档案与现代统治模式的起源", "authors": "杨光",
 "abstract": "福柯对底层阶级档案与现代性关系的深刻分析，是档案学在人文研究导向和后现代思考语境下无法绕过的思想。在《无名者的生平》这篇同名档案汇编导言，也是他二十余年档案研究的唯一总结中，福柯不仅解释了从理论分析到文献汇编的档案研究转向，强调了“让档案自己说话”的原则；而且将17—18世纪巴士底狱无名之辈的档案引入“权力-话语（知识）”关系谱系的历史反思中，推进了《规训与惩罚》中对档案与社会权力结构的探讨，从而完整回答了档案与现代统治模式起源的关系。17世纪末王印监禁文书的盛行使一种隶属行政管理的档案权力技术取代了基督教的自我坦白技术，孕育了一种通过话语掌控日常生活的微观权力机制，并在18世纪末的法国档案工作改革后逐渐发展为通过知识征服人，进而治理社会的现代规训统治模式。"},
{"issue": "2024-6", "column": "实践经纬", "title": "大模型在档案工作数智转型中的应用：新机遇、新模式和新转变", "authors": "牛力 金持 黎安润泽",
 "abstract": "档案资源形态演化、技术环境变迁和用户需求提高等内外因素变革驱动档案工作数智转型，亟待突破物理、数字双空间发展模式跃迁至知识空间。然而智能化工具的缺位导致数智转型缺少技术支点。大模型技术的出现对档案等公共服务产业造成冲击，也为档案工作全链路技术升级带来新机遇。从大模型核心技术出发，分析档案工作数智转型现状、大模型实践场景和理论研究，明确大模型技术嵌入档案工作的必要性和可行性，结合CVP技术栈思想提出知识空间档案工作“大模型+”技术嵌入框架，探索档案知识“收管存用”新模式，进而探讨大模型驱动档案工作产生的人机关系、工作场域和工作模式的新转变。"},
{"issue": "2024-6", "column": "实践经纬", "title": "RASM模式管理对象设置与分析", "authors": "黄建峰 袁平 戴敏 郑志荣 林威 严智伟",
 "abstract": "福建省档案局、福建省档案馆从国内文档管理国情出发，创新提出以“三包两结构一体化”为核心的电子文件与电子档案规范管理模式（简称RASM模式）。通过对RASM模式管理对象——信息包、元数据、数据管理流程等的研究分析，阐述RASM模式是立足我国电子文件与电子档案规范管理实践，吸收国际先进档案管理理论和经验，通过区域性实践所形成的适应文档管理国情的电子文件与电子档案规范管理实践模式。在此基础上，对其未来推广应用提出相应对策与展望，努力构建有中国特色电子档案单套管理体系。"},
{"issue": "2024-6", "column": "实践经纬", "title": "文化安全视域下非物质文化遗产档案的开放探析", "authors": "锅艳玲 司冬梅",
 "abstract": "文化安全是国家安全的重要组成部分，非物质文化遗产是中华民族文化的“根”与“魂”，其安全是文化安全的应有之义。非物质文化遗产档案是非物质文化遗产的全景记录，科学合理的开放档案有助于应对非物质文化遗产保护与传承中面临的危险。针对当前非物质文化遗产面临的失存、失真、失传、失众等主要危险，在辨析非物质文化遗产安全与档案开放关系的基础上，以档案开放为核心，从档案建设质量优化、档案利用科学规范、开放主体多元协同、开放方式“融合”等方面提出相应策略，旨在于通过档案资源赋能非物质文化遗产安全。"},
{"issue": "2024-6", "column": "实践经纬", "title": "数字档案文化的共情传播：价值旨归、生成维度与推进策略", "authors": "孙大东 赵宇",
 "abstract": "共情传播有助于提升数字档案文化建设水平与传播效能。以习近平文化思想为导向，以“共情理论”为研究视角，在探讨数字档案文化共情传播的人民性和时代性价值旨归基础上，从“发生、发起、发展、发力”四个维度将数字档案文化的共情传播阐发为“为了人民”的情感认同、“依靠人民”的情感共振、“惠及人民”的共情关注和“以人民为中心”的共情行动，并据此提出凝聚价值共识、汇集群体智慧、回应现实关切和实现合力共为的数字档案文化共情传播推进策略。"},
{"issue": "2024-6", "column": "实践经纬", "title": "基于形式与内容交互的红色档案语义表示", "authors": "王平 彭思源 李沐妍 侯景瑞",
 "abstract": "红色档案是传承红色基因和讲好红色故事的重要资源，为用好用活红色档案，档案工作需要对红色档案进行语义组织，其中语义表示是必不可少的关键环节。首先针对红色档案的多模态、主题性特征，提出了基于形式和内容交互视角的红色档案语义表示分析框架；而后通过形式语义分析和内容语义分析搭建涵盖形式层、对象层、描述层和关联层四个层次的红色档案语义表示模型，实现了从低层向高层语义逐层渐进的细粒度语义揭示；最后，以开国大典影像档案为例，验证了提出模型具有实现领域特征聚焦、揭示多粒度语义和发现多维语义关联的优势。"},
{"issue": "2024-6", "column": "实践经纬", "title": "基于档案权利考量的社会建档：生成逻辑、核心意蕴与实践策略", "authors": "王运彬 孟一凡 杨天酬 王小云",
 "abstract": "建立覆盖人民群众和民族复兴的档案资源体系，亟须妥善处理诸多建档主体之间的权利关系，即档案权利。致力于覆盖所有主体、吸纳相关主体和保障合法权益，是构建社会建档理论的缘起。理论构建之前，需厘清档案权利的相关方、利益方和保障方。理论构建之时，应依照“成为档案的权利”“管理档案的权利”和“利用档案的权利”确立社会建档的纳入范畴、驱动机理和利用转向。理论构建之后，可从宏观、中观和微观层面将其作为国家档案事业发展有益且可行的补充。"},
{"issue": "2024-6", "column": "实践经纬", "title": "基于扎根研究的村级档案服务乡村治理的模型构建", "authors": "加小双 王春蕾 张蔼",
 "abstract": "村级档案真实地记录乡村治理的内容和进程，是乡村治理行为“留痕”的重要手段，也是乡村治理记忆“建构”的内生机制。目前关于村级档案服务乡村治理的研究广度有待扩展，深度也有待进一步理论聚焦。作为探索性研究，主要以案例分析、深度访谈和实地调查为基础，通过质性的扎根理论方法进行编码分析，形成8个主范畴、40个范畴和81个初始概念，进而构建涵盖治理体系与治理能力双层结构的，以引导、带动、稳固、保障四个机制为核心的“双层-四维-八核”服务模型。"},
{"issue": "2024-6", "column": "实践经纬", "title": "破产企业档案管控的地方经验及国家制度完善", "authors": "孙军",
 "abstract": "企业破产制度的实质是国家司法程序对破产情形中的档案行政管理关系的干预，破产企业档案法律关系由此受到民商类制度和行政类制度的共同调整。当前国家层面破产企业档案管控制度未能解决两类制度并行适用时的规则衔接、机制联动等问题，而地方通过制度创新实践已经取得了诸多管控经验。分析了以司法程序为主要运行方式的企业破产制度与档案行政管理制度的适用关系，归纳了国家层面的制度缺陷所在，通过总结地方破产企业档案处置制度经验及不足，提出完善国家制度的路径。"},
{"issue": "2024-6", "column": "古文书学", "title": "清代公文书作伪原因、辨伪方式及处理实态", "authors": "赵彦昌 韩瑞鹏",
 "abstract": "从档案文本探究清代伪造公文书问题，是从历史汲取中华民族优秀法治文化的过程，有助于充分发掘历史档案的应用价值和社会功能。通过整理和分析中国第一历史档案馆馆藏相关档案，发现清代伪造公文书行为多与钱财、身份、情感等因素有关。面对此类案件时，官员会根据公文书制度、内容、外形等细节辨别公文书真伪，随后将案件分为伪造皇帝文书案件和伪造官文书案件。相同的是，二者判定过程中都要依照律例规定，但不得与皇帝决定相抵触。"},
{"issue": "2024-6", "column": "档案史论", "title": "民国时期档案学著作出版述论", "authors": "黎飞",
 "abstract": "民国时期，档案工作实践和档案事业发展的推动与刺激、出版业发展的重要保障作用和档案学人的辛勤编纂等因素促使各类档案学著作陆续出版。这一时期，档案学著作出版具有出版主体多为政府部门、出版内容注重实用性、出版地集中分布等特点。总体而言，民国时期档案学著作的出版不仅推动了档案学的学科化发展，加速了档案学知识的传播，留下了研究民国档案学史、档案事业史和档案学人的宝贵文献，而且也有助于推动中华文化的传承与发展，影响深远。"},
{"issue": "2024-6", "column": "档案保护", "title": "生成对抗网络在老照片档案智能化修复中的应用探究", "authors": "徐辛酉 杨晓芳",
 "abstract": "生成对抗网络作为近年出现的一类深度学习模型，在数字图像智能化修复领域展示出较好的应用前景。通过文献回顾及考究该网络在老照片档案智能化修复中的特点，发现其仿真度好、灵活性强、处理效率高、数据可扩增。在具体技术实现机理及过程中，也验证了其在老照片档案智能化去模糊、修补及修补效率等方面效果良好，值得推广，但同时也要防范其中的“深度伪造”问题。"},
{"issue": "2024-6", "column": "档案教育", "title": "档案产业学院：档案产业发展需求与档案人才培养的耦合", "authors": "任琼辉 李璐璐",
 "abstract": "档案产业学院有助于实现档案产业发展需求与档案人才培养的耦合。作为一种聚焦档案行业发展和档案科技创新的实体，档案产业学院具有服务面向特定性、合作主体包容性及资源要素多样性的特征。档案产业学院对于教育链、人才链和产业链三个方面的发展具有积极意义。当前理论成果、政策要求、实践探索和专业发展共同构成档案产业学院建设的动力体系。档案产业学院的建设路径，应聚焦建设目标、建设模式、建设任务和课程体系等四个方面。"},
]
